'use strict';
const spaces={
 treasury:{name:'财政会议室',english:'THE TREASURY',accent:'#ddb575'},exchange:{name:'证券交易大厅',english:'SOVEREIGN EXCHANGE',accent:'#7adab8'},reserve:{name:'央行清算厅',english:'THE CLEARING HOUSE',accent:'#86d4d4'},factory:{name:'工业厂区',english:'THE FOUNDRY',accent:'#eeaa70'},harbor:{name:'港口调度室',english:'THE HARBOUR',accent:'#8dccdb'},academy:{name:'技术学院',english:'THE ACADEMY',accent:'#e5c488'},clinic:{name:'社区诊所',english:'COMMUNITY CARE',accent:'#a5d9bf'},diplomacy:{name:'外交会议厅',english:'THE NEGOTIATION',accent:'#d9afbc'},cabinet:{name:'内阁议事厅',english:'THE CABINET',accent:'#d4bd80'},power:{name:'电网调度中心',english:'GRID CONTROL',accent:'#cfe592'},construction:{name:'勘探与施工现场',english:'THE PROJECT SITE',accent:'#dec29a'},commons:{name:'公共服务中心',english:'THE COMMONS',accent:'#b6d39e'}
};
const roomSpaces={captain:['cabinet','cabinet','diplomacy'],finance:['treasury','exchange','treasury'],central_bank:['reserve','reserve','exchange'],industry:['power','factory','construction'],trade:['harbor','harbor','harbor'],social:['academy','commons','clinic']};
let activeSpace='treasury',fieldIndex=0,fieldPage='controls',routeQuiet=false,sceneSection='',quantityEditing=null;
const oldRender=render,oldSetRole=setRole,oldSavePolicy=savePolicy,oldShowRoom=showRoom;
function glyph(id){const paths={coin:'<ellipse cx="40" cy="46" rx="25" ry="10"/><path d="M15 31v15m50-15v15"/><ellipse cx="40" cy="31" rx="25" ry="10"/><path d="M40 24v14m-7-10h11l-8 7h11"/>',port:'<path d="M11 54h58M20 54V22h38v32M20 28h45M53 28v14l-6 4M29 54V38h13v16M14 60h48l8-8"/>',bank:'<path d="M9 30l31-18 31 18H9Zm5 32h52M20 35v22m13-22v22m14-22v22m14-22v22M9 67h62"/>',ship:'<path d="M10 49h60l-13 16H25L10 49Zm30 0V10L61 42H40M35 19 15 43h20M8 71q8-7 16 0t16 0t16 0t16 0"/>',factory:'<path d="M10 66V35l20 10V29l20 13V24h19v42H10Zm7-9h6m12 0h6m13 0h6M54 24V12h10v12"/>',person:'<circle cx="40" cy="20" r="9"/><path d="M20 65V44a20 20 0 0 1 40 0v21M30 44v27m20-27v27"/>',power:'<path d="M43 8 19 44h20l-4 28 27-41H42l1-23Z"/>',book:'<path d="M40 65c-10-8-20-8-30-5V16c10-3 20-3 30 5 10-8 20-8 30-5v44c-10-3-20-3-30 5Zm0-44v44M18 28l14 3m-14 9 14 3m16-12 14-3m-14 15 14-3"/>',cross:'<path d="M29 10h22v19h19v22H51v19H29V51H10V29h19V10Z"/>',seal:'<circle cx="40" cy="32" r="22"/><path d="m27 51-5 23 18-10 18 10-5-23M28 32l8 8 17-18"/>',crane:'<path d="M18 70V12h9v58M12 70h31M12 22h57L27 10M58 22v26l-6 5m-4 0h10M28 58h40v12H28"/>',globe:'<circle cx="40" cy="40" r="29"/><ellipse cx="40" cy="40" rx="13" ry="29"/><path d="M12 32h56M12 49h56"/>'};return `<svg class="object-glyph" viewBox="0 0 80 80" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${paths[id]||paths.seal}</svg>`;}
function pathTo(path,replace=false){if(routeQuiet)return;const u=`?role=${role}${countryScope?'&country='+countryScope:''}#${path}`;if(location.search+location.hash!==u)history[replace?'replaceState':'pushState']({role,path},'',u);}
function scene(space,title,subtitle,body,footer='',kind='play'){
 activeSpace=space;document.body.classList.add('in-scene');document.body.dataset.scene=space;const meta=spaces[space];
 patchSceneHTML(`<section class="immersive-scene ${kind}" data-space="${space}" style="--scene-accent:${meta.accent};--scene-image:url('assets/${space}.png')" aria-label="${esc(title)}"><div class="scene-environment"></div><div class="scene-atmosphere" aria-hidden="true"></div><header class="scene-header"><button class="scene-back" data-cmd="close" aria-label="返回地图">← <span>共和国</span></button><div class="scene-location"><small>ECONMIND / ${meta.english}</small><span>${meta.name}</span></div><div class="scene-clock"><small>${roles[role].name}</small><strong>第 ${s.day} 日</strong></div><button class="scene-menu" data-cmd="codex" aria-label="全部行动">全部行动 ↗</button></header><div class="scene-heading"><span class="scene-kicker">${esc(sceneSection||'SEASON 1 · 北港启航')}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="scene-content">${body}</div>${footer?`<footer class="scene-footer">${footer}</footer>`:''}<div class="scene-edition">本地场景 · 模拟时间</div></section>`);
}
function infoLine(label,value,unit=''){return `<div class="info-line"><span>${label}</span><strong>${value}<small>${unit}</small></strong></div>`;}
function specimen(icon,title,value,unit,note=''){return `<div class="specimen">${glyph(icon)}<small>${title}</small><strong>${value}<em>${unit}</em></strong>${note?`<p>${note}</p>`:''}</div>`;}
function scenicButton(label,cmd,attrs='',secondary=false){return `<button class="scene-button ${secondary?'subtle':''}" data-cmd="${cmd}" ${attrs}>${label}<span>↗</span></button>`;}
function roomFooter(i,action='',note=''){return `<div class="footer-left">${action}${note?`<span class="footer-note">${note}</span>`:''}</div><div class="footer-right">${scenicButton('相关行动','codex',`data-id="${i}"`,true)}<button class="text-button" data-cmd="history">时间线</button></div>`;}
function controlRail(label,key,value,min,max,step,unit){const pct=max>min?Math.max(0,Math.min(100,(value-min)/(max-min)*100)):0;return `<div class="object-control" data-scene-control="${key}"><div class="control-caption"><span>${label}</span><button class="precision-toggle" data-cmd="precision" data-id="${key}">精确数值</button></div><div class="control-display"><button data-cmd="nudge" data-id="${key}" data-delta="-1" aria-label="减少${label}">−</button><output data-output="${key}">${fmt(value)}</output><span>${unit}</span><button data-cmd="nudge" data-id="${key}" data-delta="1" aria-label="增加${label}">+</button></div><input type="range" data-control="${key}" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${value}" style="--value:${pct}%"><div class="rail-limits"><span>${fmt(min)} ${unit}</span><span>${fmt(max)} ${unit}</span></div><input class="precise-value ${quantityEditing===key?'':'hidden'}" aria-label="${label}精确值" type="number" data-control="${key}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function dial(label,key,value,min,max,step,unit){const angle=240*(value-min)/(max-min||1)-120;return `<div class="dial-instrument"><div class="dial-face" style="--angle:${angle}deg"><div class="dial-ticks"></div><div class="dial-needle"></div><div class="dial-center"><small>${label}</small><strong>${fmt(value)}</strong><span>${unit}</span></div></div>${controlRail(label,key,value,min,max,step,unit)}</div>`;}
function unitPeople(n,status=''){return `<div class="citizen-group ${status}">${Array.from({length:Math.min(24,Math.ceil(n/5))},(_,i)=>`<span class="citizen" style="--delay:${i*30}ms">${glyph('person')}</span>`).join('')}</div>`;}
function openRoomScene(i){const funcs={captain:captainScene,finance:financeScene,central_bank:reserveScene,industry:industryScene,trade:tradeScene,social:socialScene};funcs[role](i);}
renderRoom=function(){if(typeof view==='number')openRoomScene(view);else if(view==='module')renderEditor();else if(view==='codex')renderCodex();else if(view==='history')genericHistory();else if(view==='roles')rolePicker();else if(view==='policies')policies();else if(view!==null)help();};
render=function(){oldRender();if(view===null){document.body.classList.remove('in-scene');document.body.dataset.scene='';pathTo('map',true);}else document.body.classList.add('in-scene');decorateHome();};
setRole=function(r){oldSetRole(r);document.body.classList.remove('in-scene');decorateHome();};
showRoom=function(i){view=Number(i);sceneSection='';pathTo('scene/'+role+'/'+view);renderRoom();};
sheet=function(title,body,eyebrow=''){sceneSection='';scene(roomSpaces[role][typeof view==='number'?view:0],title,eyebrow,`<div class="reading-page">${body}</div>`,'','reading');};
function decorateHome(){document.body.dataset.role=role;$$('.action-card').forEach((el,i)=>{el.style.setProperty('--thumb',`url('assets/${roomSpaces[role][i]}.png')`);});}
commands.close=()=>{view=null;sceneSection='';$('#overlay').innerHTML='';document.body.classList.remove('in-scene');pathTo('map');oldRender();decorateHome();};
commands.precision=b=>{quantityEditing=quantityEditing===b.dataset.id?null:b.dataset.id;renderRoom();};
commands.nudge=b=>{const key=b.dataset.id,input=document.querySelector(`input[type=range][data-control="${key}"]`);if(!input)return;input.value=String(Math.min(Number(input.max),Math.max(Number(input.min),Number(input.value)+Number(input.step||1)*Number(b.dataset.delta))));input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));};
function financeScene(i){
 if(i===0){const n=s.allocated/5e6;scene('treasury','北港建设拨款','项目已获得银行与私人出资。国库资金到位后，建设按里程碑推进。',`<div class="treasury-stage"><aside class="resource-tray"><div class="instrument-label">TREASURY ALLOCATION</div><h2>可分配资金</h2><div class="large-reading">${compact(40e6-s.allocated)}<span>LNY</span></div><div class="cash-stacks" data-drop="return">${Array.from({length:8-n},(_,j)=>`<button class="cash-stack" draggable="${!s.committed}" data-token="fund" data-cmd="fund" data-delta="1" aria-label="拨入500万LNY" ${s.committed?'disabled':''}><span>5,000,000</span><small>LNY</small></button>`).join('')}</div><p class="object-caption">每枚代表 5M LNY<br>拖入港口模型，或点击分配。</p></aside><div class="construction-model" data-drop="fund"><div class="model-plinth">${glyph('port')}<div class="model-light"></div></div><div class="model-label"><span>NORTH HARBOUR / PHASE 01</span><h2>北港扩建</h2><div class="construction-slots">${Array.from({length:8},(_,j)=>`<button class="fund-slot ${j<n?'filled':''}" data-cmd="${j<n?'fund':'fund'}" data-delta="${j<n?-1:1}" aria-label="${j<n?'收回':'拨入'}500万LNY" ${s.committed?'disabled':''}>${j<n?'◆':'+'}</button>`).join('')}</div><strong>${compact(s.allocated)} <small>/ 40M LNY</small></strong><p>银行 20M · 私人 30M · 项目总额 90M LNY</p></div></div><aside class="signature-stack"><div class="instrument-label">PROJECT CONSENT</div><h3>建设许可</h3><p>项目所有者：产业部长<br>批准绑定当前资金配置。</p>${s.approvals.map((x,j)=>`<button class="signature ${x?'signed':''}" data-cmd="finance-approve" data-id="${j}" ${x||s.allocated!==40e6||s.committed?'disabled':''}><span>${['产业部长','Captain'][j]}</span><b>${x?'已确认':'模拟席位确认'}</b><i>${x?'✓':'○'}</i></button>`).join('')}<div class="seal-note">${s.committed?'资金已承诺':s.allocated<40e6?'资金缺口 '+compact(40e6-s.allocated)+' LNY':'资金配置完整'}</div></aside></div>`,roomFooter(i,scenicButton(s.committed?'资金已承诺':'承诺建设资金','fund-commit',s.committed||s.allocated!==40e6||!s.approvals.every(Boolean)?'disabled':''),'先承诺，后按里程碑付款。'));}
 else if(i===1){let allocated=Math.min(s.bondOffer,20e6),net=allocated*.98-200000;scene('exchange','主权债券发行','国内申购席位已经报价。拟发行面值并不等于实际成交额。',`<div class="exchange-stage"><div class="market-board"><div class="board-header"><span>国内申购 / 固定样例</span><b>98.00 <small>% 面值</small></b></div><div class="bid-lane"><span>01</span>${glyph('bank')}<div><h3>国内银行</h3><div class="order-depth"><i style="width:100%"></i></div></div><strong>12M<small>LNY</small></strong></div><div class="bid-lane"><span>02</span>${glyph('person')}<div><h3>其他投资者</h3><div class="order-depth"><i style="width:66.66%"></i></div></div><strong>8M<small>LNY</small></strong></div><div class="market-note">最大申购面值 20M LNY · 无海外买盘</div></div><div class="issuance-control">${dial('拟发行面值','bondOffer',s.bondOffer,1e6,40e6,1e6,'LNY')}</div><aside class="trade-ticket"><span class="instrument-label">ALLOCATION TICKET</span><h3>${s.bond?(s.settled?'交割完成':'等待交割'):'预期配售'}</h3>${infoLine('成交面值',compact(allocated),'LNY')}${infoLine('发行费','0.2M','LNY')}${infoLine('净现金',compact(net),'LNY')}${infoLine('未成交',compact(s.bondOffer-allocated),'LNY')}<p>票息 3%/年 · 360 日到期<br>发行次日交割，届时计入国库。</p></aside></div>`,roomFooter(i,scenicButton(s.bond?'本次发行已完成':'发行并配售','issue',s.bond?'disabled':'')));}
 else{const events=[{day:130,label:'工资与税款',value:-7e6},{day:136,label:'既有债务本息',value:-22e6},{day:138,label:'既有采购',value:-6e6}];if(s.committed)s.projectDays.forEach((d,j)=>events.push({day:d,label:['场地施工','主体开工'][j],value:-20e6}));if(s.bond)events.push({day:s.bond.day,label:'债券交割',value:s.bond.net});events.sort((a,b)=>a.day-b.day);scene('treasury','国库支付日','建设资金、债务与工资按各自日期支付。现金变化与工地阶段同步。',`<div class="payment-stage"><div class="cash-balance"><span class="instrument-label">TREASURY CASH</span><div class="large-reading">${compact(s.cash)}<span>LNY</span></div><p>建设已支付 ${compact(s.paid)} LNY</p>${glyph(s.paid===40e6?'crane':'coin')}</div><div class="payment-calendar">${events.map((e,j)=>`<div class="payment-stop ${e.day<=s.day?'passed':''}"><span class="calendar-dot"></span><div class="calendar-date"><small>模拟日</small><b>${e.day}</b></div><div><h3>${e.label}</h3><p>${e.day<=s.day?'已经结算':'等待到期'}</p></div><strong>${e.value>0?'+':''}${compact(e.value)}<small>LNY</small></strong></div>`).join('')}</div><div class="construction-progress">${glyph('crane')}<span>北港建设</span><h2>${s.paid===40e6?'主体开工':s.paid?'场地施工':s.committed?'等待首款':'尚未承诺'}</h2><div class="thin-progress"><i style="width:${s.paid/40e6*100}%"></i></div></div></div>`,roomFooter(i,scenicButton('推进至下一事件','next-event',Number.isFinite(nextEvent())?'':'disabled'),'当前：第 '+s.day+' 模拟日'));}
}
function captainScene(i){const p=plans[s.plan],support=s.support.reduce((a,b)=>a+b,0);if(i===0)scene('cabinet','北港人力议程','首批 60 人到岗可以启动第一阶段。更快抵达与一次覆盖更多岗位，需要不同投入。',`<div class="cabinet-stage"><div class="agenda-folios">${Object.entries(plans).map(([id,x],j)=>`<button class="agenda-folio ${id===s.plan?'selected':''}" data-cmd="plan" data-id="${id}" ${s.active?'disabled':''}><small>议程 0${j+1}</small>${glyph(['book','ship','globe'][j])}<h2>${x.title}</h2><div class="folio-metric">${x.n}<span>人</span></div><p>${x.days+7} 日到岗<br>${compact(x.cost)} LNY<br>${x.capital} 政治资本</p><span class="folio-mark">${id===s.plan?'当前方案':'选择方案'}</span></button>`).join('')}</div><div class="cabinet-support"><span class="instrument-label">POLITICAL SUPPORT</span><h3>议程支持</h3><p>可用 ${s.capital-support} 点 · 每个席位至少 4 点</p><div class="seat-support">${['财政','社会','Captain'].map((name,j)=>`<div class="support-seat"><strong>${name}</strong><div>${Array.from({length:Math.min(8,s.support[j])},()=>'<i></i>').join('')}</div><span><button data-cmd="support" data-id="${j}" data-delta="-1" ${s.active?'disabled':''}>−</button><b>${s.support[j]}</b><button data-cmd="support" data-id="${j}" data-delta="1" ${s.active?'disabled':''}>+</button></span></div>`).join('')}</div><button class="text-button" data-cmd="support-base" ${s.active?'disabled':''}>分配基础支持</button></div></div>`,roomFooter(i,scenicButton('进入席位表决','room','data-id="1"'),'任何方案修改都会使旧批准失效。'));
 else if(i===1)scene('cabinet','内阁席位表决',`${p.title} · 议程版本 ${s.version}。每个席位对同一版本分别确认。`, `<div class="vote-stage">${['财政部长','社会部长','Captain'].map((name,j)=>`<div class="voting-seat ${s.approvals[j]?'approved':''}"><div class="seat-medallion">${glyph(j===0?'coin':j===1?'person':'seal')}</div><h2>${name}</h2><span>支持 ${s.support[j]} / 4 点</span><p>${s.approvals[j]?'已批准当前版本':'等待席位回应'}</p>${scenicButton(s.approvals[j]?'已批准':'等待本职签署','approve',`data-id="${j}" ${s.approvals[j]||s.support[j]<4||s.active?'disabled':''}`,true)}</div>`).join('')}</div><div class="agenda-strip"><span>${p.title}</span><b>${compact(p.cost)} LNY</b><b>${p.n} 人</b><b>${Math.max(support,p.capital)} 政治资本</b></div>`,roomFooter(i,scenicButton(s.active?'计划执行中':'执行已批准议程','enact',s.active||!s.approvals.every(Boolean)?'disabled':''),'模拟席位回应仅用于本地体验。'));
 else scene('diplomacy','公开承诺与危机','承诺按实际到岗人数兑现。协调状态与人才执行阶段分别记录。',`<div class="commitment-stage"><div class="promise-document"><span class="instrument-label">PUBLIC COMMITMENT</span><h2>北港技术人员到岗</h2><div class="promise-amount">${s.workers}<small>/ 80 人</small></div><p>${s.commitment?'截止第 '+s.commitment+' 日':'尚未公布截止日'}</p>${scenicButton(s.commitment?'承诺已发布':'发布到岗目标','commitment',s.commitment?'disabled':'')}<div class="embossed-seal">${glyph('seal')}</div></div><div class="diplomatic-timeline">${infoLine('人才齐备',s.active?'第 '+s.active.graduateDay+' 日':'尚未生效')}${infoLine('岗位到达',s.active?'第 '+s.active.arrivalDay+' 日':'尚未生效')}${infoLine('承诺状态',!s.commitment?'未发布':s.workers>=80?'已兑现':s.day>s.commitment?'未兑现':'进行中')}<h3>危机协调</h3><p>${s.crisis}</p>${scenicButton(s.crisis==='常态'?'启动加强协调':'退出加强协调','crisis','',true)}</div></div>`,roomFooter(i));
}
function reserveScene(i){if(i===0){const b=s.banks[s.bank],limit=Math.min(s.cash,b.collateral*.8-b.loan);scene('reserve','银行流动性调配','抵押品折后价值决定贷款额度。资金沿清算网络到账，按合同期限归还。',`<div class="clearing-stage"><div class="reserve-source">${glyph('bank')}<span>央行资金</span><strong>${compact(s.cash)}<small>LNY</small></strong><div class="flow-cable"></div></div><div class="bank-nodes">${s.banks.map((x,j)=>`<button class="bank-node ${j===s.bank?'selected':''} ${x.loan>=x.gap?'covered':''}" data-cmd="bank" data-id="${j}">${glyph('bank')}<h2>${x.name}</h2><span>缺口 ${compact(Math.max(0,x.gap-x.loan))} LNY</span><div class="thin-progress"><i style="width:${Math.min(100,x.loan/Math.max(1,x.gap)*100)}%"></i></div><p>抵押额度 ${compact(x.collateral*.8)} LNY</p></button>`).join('')}</div><div class="loan-instrument">${controlRail('本次贷款','amount',s.amount,0,limit,200000,'LNY')}${infoLine('贷款期限',7,'模拟日')}${infoLine('合同年利率',(s.rate+.5).toFixed(2),'%')}${infoLine('放款后缺口',compact(Math.max(0,b.gap-b.loan-s.amount)),'LNY')}</div></div>`,roomFooter(i,scenicButton('向'+b.name+'放款','lend',s.amount<=0||s.amount>limit?'disabled':''),'抵押折扣 20% · 样例银行按期偿还'));}
 else if(i===1)scene('reserve','政策利率控制台','政策公布后影响新贷款报价。已经签订的固定利率合同保持原利率。',`<div class="rate-stage"><div class="rate-reference"><span class="instrument-label">CURRENT POLICY RATE</span><strong>${s.rate.toFixed(2)}<small>%</small></strong><p>已公布政策利率</p></div>${dial('拟公布利率','rateDraft',s.rateDraft??s.rate,0,10,.25,'%')}<div class="rate-reference"><span class="instrument-label">NEW COLLATERALISED LOANS</span><strong>${((s.rateDraft??s.rate)+.5).toFixed(2)}<small>%</small></strong><p>拟公布后新贷款报价<br>样例加点 50 bp</p></div></div>`,roomFooter(i,scenicButton('公布政策利率','announce-rate'),'每档 25 bp · 1 bp = 0.01 个百分点'));
 else scene('exchange','外汇双边结算','按同一报价同时结算两条资产。卖出外汇后，对应本币资产增加。',`<div class="fx-stage">${specimen('globe','外汇储备',compact(s.fx),'GCU','本次卖出 '+compact(s.fxAmount)+' GCU')}<div class="fx-transfer"><div class="fx-arrows">⇄</div><strong>7.00 <small>LNY / GCU</small></strong><span>场景固定报价</span></div>${specimen('coin','本币资产',compact(s.cash),'LNY','本次回收 '+compact(s.fxAmount*7)+' LNY')}<div class="fx-amount">${controlRail('卖出外汇','fxAmount',s.fxAmount,0,Math.min(s.fx,10e6),1e5,'GCU')}</div></div>`,roomFooter(i,scenicButton('确认双边成交','fx',s.fxAmount<=0||s.fxAmount>s.fx?'disabled':'')));
}
function industryScene(i){const p=production();if(i===0)scene('power','工业电网调度','200 MWh/日的工业供电在两条产线之间分配。民生基础用电另有 60 MWh/日保障。',`<div class="grid-stage"><div class="grid-generator">${glyph('power')}<strong>200<small>MWh / 日</small></strong><span>工业供给</span></div><div class="grid-consumers"><div class="grid-consumer" data-energy-drop="steel">${glyph('factory')}<h2>钢厂</h2><strong>${s.powerSteel}<small>MWh/日</small></strong><div class="energy-blocks">${Array.from({length:s.powerSteel/10},()=>`<button draggable="true" data-energy="steel" data-cmd="energy-shift" data-id="machines" aria-label="向机械厂转移10MWh">ϟ</button>`).join('')}</div><p>预计 ${p.steel} tonne/日</p></div><div class="grid-consumer" data-energy-drop="machines">${glyph('crane')}<h2>机械厂</h2><strong>${200-s.powerSteel}<small>MWh/日</small></strong><div class="energy-blocks">${Array.from({length:(200-s.powerSteel)/10},()=>`<button draggable="true" data-energy="machines" data-cmd="energy-shift" data-id="steel" aria-label="向钢厂转移10MWh">ϟ</button>`).join('')}</div><p>预计 ${p.machines} equipment_unit/日</p></div></div><div class="grid-adjustment">${controlRail('钢厂供电','powerSteel',s.powerSteel,0,200,10,'MWh/日')}<p>每个电力单元代表 10 MWh/日。拖到另一产线，或点击转移。</p></div></div>`,roomFooter(i,scenicButton('进入生产批次','room','data-id="1"')));
 else if(i===1){const batch=s.batchDays||1;scene('factory','原料进入生产线','矿石先加工成钢材，机械生产再消耗钢材。连续运行时，每一日重新核对资源瓶颈。',`<div class="factory-stage"><div class="production-chain">${[['construction','铁矿石',s.ore,'tonne'],['factory','钢材',s.steel,'tonne'],['crane','机械',s.machines,'equipment_unit']].map(([ic,n,v,u],j)=>`${j?'<div class="conveyor"><i></i><i></i><i></i></div>':''}<div class="production-station">${glyph(ic==='construction'?'crane':ic)}<h2>${n}</h2><strong>${fmt(v)}<small>${u}</small></strong><p>${j===0?'每吨钢消耗 2 tonne 矿石':j===1?'下日生产 '+p.steel+' tonne':'下日生产 '+p.machines+' 台'}</p></div>`).join('')}</div><div class="production-console">${controlRail('钢材日产目标','target',s.target,0,s.capacity,5,'tonne/日')}<div class="batch-selector"><span class="instrument-label">PRODUCTION RUN</span><h3>运行批次</h3><div>${[1,3,5].map(n=>`<button class="${batch===n?'active':''}" data-cmd="batch-days" data-id="${n}">${n}<small>模拟日</small></button>`).join('')}</div><p>首日支出 ${fmt(p.steel*20+p.machines*100)} LNY<br>可用现金 ${fmt(s.cash)} LNY</p></div></div></div>`,roomFooter(i,scenicButton('启动 '+batch+' 日生产批次','run-batch'),'原料与现金不足时，实际产量自动受限。'));}
 else scene('construction','钢厂扩建工程','建设投入产生未来产能。完工后，工人、供电和原料约束仍然存在。',`<div class="engineering-stage"><div class="blueprint"><div class="blueprint-grid"></div>${glyph('factory')}<span>STEEL WORKS / EXTENSION</span><h2>钢厂二期</h2><div class="blueprint-dimension">+40 tonne / 日</div></div><div class="engineering-note"><span class="instrument-label">CONSTRUCTION STAGES</span>${infoLine('建设资金','20,000','LNY')}${infoLine('建设周期',5,'模拟日')}${infoLine('当前产能',s.capacity,'tonne/日')}<div class="engineering-phases"><span class="${s.expansion?'done':''}">资金投入</span><i></i><span class="${s.expansion?'done':''}">施工</span><i></i><span class="${s.expansion?.done?'done':''}">投产</span></div><p>${s.expansion?(s.expansion.done?'工程已投产':'第 '+s.expansion.end+' 日完工'):'已批准产业建设预算。支付后开工。'}</p></div></div>`,roomFooter(i,scenicButton(s.expansion?'工程已开工':'支付并开工','expand',s.expansion||s.cash<20000?'disabled':'')));
}
function tradeScene(i){const p=suppliers[s.supplier],q=quote();if(i===0)scene('harbor','航线与货源','近港航程较短，远港单价较低。供应商库存有限，每笔订单都占用真实货量。',`<div class="nautical-stage"><div class="nautical-map"><div class="compass-rose">N<span>✧</span>S</div><svg viewBox="0 0 700 300" class="shipping-chart" aria-hidden="true"><path class="coast" d="M20 30 90 50 110 110 190 80 230 150 190 190 270 260 30 260Z"/><path class="coast" d="M560 35 670 20 670 265 570 230 605 170 545 140Z"/><path class="sea-route near" d="M215 155 Q380 95 590 150"/><path class="sea-route far" d="M90 230 Q400 360 590 150"/></svg><button class="port-marker near ${s.supplier==='near'?'selected':''}" data-cmd="supplier" data-id="near">${glyph('port')}<b>阿斯特近港</b><span>3 日航程</span></button><button class="port-marker far ${s.supplier==='far'?'selected':''}" data-cmd="supplier" data-id="far">${glyph('ship')}<b>索拉远港</b><span>7 日航程</span></button><div class="port-marker destination">${glyph('crane')}<b>北港</b><span>${s.stock} tonne 库存</span></div></div><div class="shipping-order"><span class="instrument-label">${p.name}</span><h2>${p.price}<small>GCU / tonne</small></h2><p>运费 ${p.freight} · 保险 5 GCU/tonne<br>剩余供应 ${s.supply[s.supplier]} tonne</p>${controlRail('采购钢材','quantity',s.quantity,0,s.supply[s.supplier],5,'tonne')}${infoLine('含税总额',fmt(q.total),'GCU')}${infoLine('预计到港',s.day+p.days,'模拟日')}</div></div>`,roomFooter(i,scenicButton('进入装船作业','room','data-id="1"')));
 else if(i===1){const manifest=s.manifest;scene('harbor','码头配货与装船',`${p.name} → 北港。企业使用自有 GCU 付款，官方外汇储备不参与本笔订单。`,`<div class="loading-stage"><div class="cargo-hold"><div class="cargo-title"><span>STEEL CARGO / 钢材</span><strong>${s.quantity} <small>tonne</small></strong></div><div class="cargo-crates ${manifest?'loaded':''}">${Array.from({length:Math.min(20,Math.ceil(s.quantity/5))},(_,j)=>`<div class="cargo-crate" style="--crate:${j}"><span>钢</span><small>5 t</small></div>`).join('')}</div><p>${manifest?'配货完成 · 清单已锁定':'货物待配装 · 5 tonne / 标准货组'}</p>${!manifest?scenicButton('完成配货并锁定报价','pack',s.quantity<=0||q.total>s.cash?'disabled':'',true):`<span class="loading-seal">MANIFEST READY</span><button class="text-button" data-cmd="unpack">调整配货</button>`}</div><aside class="cargo-manifest"><span class="instrument-label">CARGO MANIFEST</span><h2>运输清单</h2>${[['货款',q.goods],['运费',q.freight],['保险',q.insurance],['关税',q.tax]].map(([n,v])=>infoLine(n,fmt(v),'GCU')).join('')}<div class="manifest-total">${fmt(q.total)}<small>GCU</small></div><p>付款后企业现金 ${fmt(s.cash-q.total)} GCU<br>预计第 ${s.day+p.days} 日到港</p></aside></div>`,roomFooter(i,scenicButton('签约付款并离港','ship',!manifest||q.total>s.cash?'disabled':''),'签约后锁定条款，只有到港才增加库存。'));}
 else scene('harbor','航程与海关','船只按模拟日推进。订单发出后，运输中的货物独立记录。',`<div class="voyage-stage">${s.shipments.length?s.shipments.map(x=>{const t=Math.min(1,(s.day-x.start)/(x.arrival-x.start));return `<div class="voyage"><div class="voyage-heading"><h2>${x.name} → 北港</h2><strong>${x.quantity}<small>tonne</small></strong></div><div class="voyage-sea"><span class="voyage-origin">${glyph('port')}</span><div class="voyage-route"></div><span class="moving-vessel" style="left:${10+t*78}%">${glyph('ship')}</span><span class="voyage-destination">${glyph('crane')}</span></div><div class="voyage-meta"><span>第 ${x.start} 日离港</span><b>${x.arrived?'已经到港':'剩余 '+(x.arrival-s.day)+' 日'}</b><span>第 ${x.arrival} 日到港</span></div></div>`}).join(''):`<div class="empty-voyage">${glyph('ship')}<h2>港口等待第一艘货船</h2>${scenicButton('选择货源','room','data-id="0"',true)}</div>`}<div class="customs-lever">${controlRail('新订单关税','tariff',s.tariff,0,30,1,'%')}<p>新关税只影响后续签约订单。</p></div></div>`,roomFooter(i,scenicButton('推进至下一到港日','next-event',Number.isFinite(nextEvent())?'':'disabled')));
}
function socialScene(i){if(i===0){const active=s.programme&&!s.programme.done,n=active?s.programme.n:s.seats;scene('academy','技术人才培养','有限师资、教学容量与培训预算共同决定招生人数。毕业后仍需安排就业。',`<div class="academy-stage"><div class="classroom-layout"><div class="teaching-board"><span>TECHNICAL PROGRAMME</span><h2>${active?'培养进行中':'本期招生安排'}</h2><p>${active?'第 '+s.programme.end+' 日毕业':'30 模拟日 · 每人 2,000 LNY'}</p></div><div class="classroom-seats">${Array.from({length:16},(_,j)=>`<button class="student-seat ${j*5<n?'occupied':''}" data-cmd="class-seat" data-id="${j}" ${active?'disabled':''} aria-label="安排${(j+1)*5}名学员">${glyph('person')}<small>${j*5<n?'5 人':'空位'}</small></button>`).join('')}</div><p class="object-caption">每组座位代表 5 人 · 教师容量 80 人 · 设施容量 100 人</p></div><aside class="academy-enrollment">${specimen('book','本期人数',n,'人')}${infoLine('培训支出',fmt(n*2000),'LNY')}${infoLine('预计毕业',Math.floor(n*.9),'人')}${infoLine('可用预算',fmt(s.funds),'LNY')}<p>样例毕业率 90%。未毕业人员回到原人群，不会凭空消失。</p>${active?scenicButton('推进到下一事件','next-event','',true):controlRail('精确招生人数','seats',s.seats,0,80,1,'人')}</aside></div>`,roomFooter(i,scenicButton(active?'本期培养中':'缴费并开班','train',active||s.seats<=0||s.seats*2000>s.funds?'disabled':'')));}
 else {if(i===1){const pending=s.placements.filter(x=>!x.done).reduce((a,b)=>a+b.n,0);scene('commons','岗位匹配与入职','具备技能的人员可以进入岗位安排。入职途中与正式到岗分别计数。',`<div class="placement-stage"><div class="population-pool"><span class="instrument-label">AVAILABLE TALENT</span><h2>待匹配人才</h2>${unitPeople(s.skilled)}<strong>${s.skilled}<small>人</small></strong></div><div class="placement-transfer"><span>岗位安排</span><div class="transfer-arrow">→</div>${controlRail('本次安排','match',s.match,0,Math.min(s.skilled,s.vacancies-pending),5,'人')}<small>入职周期 7 模拟日</small></div><div class="employment-gates"><div><h3>入职途中</h3>${unitPeople(pending,'travelling')}<strong>${pending}<small>人</small></strong></div><div><h3>正式到岗</h3>${unitPeople(s.placed,'placed')}<strong>${s.placed}<small>人</small></strong></div></div></div>`,roomFooter(i,scenicButton('安排岗位匹配','match',s.match<=0||s.match>s.skilled?'disabled':''),pending?'下一批到岗：第 '+nextEvent()+' 日':'当前空缺 '+s.vacancies+' 人'));}else scene('clinic','社区接诊安排','医疗预算和本批接诊容量共同约束服务人数。完成服务后才减少等候队列。',`<div class="clinic-stage"><div class="waiting-room"><span class="instrument-label">WAITING AREA</span><h2>等候接诊</h2><div class="patient-groups">${Array.from({length:Math.ceil(s.backlog/10)},(_,j)=>`<button class="patient-group ${j*10<s.clinic?'selected':''}" data-cmd="patient-group" data-id="${j}" aria-label="安排${Math.min(60,(j+1)*10,s.backlog)}人接诊">${glyph('person')}<span>${Math.min(10,s.backlog-j*10)} 人</span></button>`).join('')}</div><p>共 ${s.backlog} 人等候 · 每组至多 10 人</p></div><div class="consultation-room">${glyph('cross')}<h2>本批接诊</h2><strong>${s.clinic}<small>/ 60 人</small></strong><div class="consultation-slots">${Array.from({length:6},(_,j)=>`<i class="${j*10<s.clinic?'filled':''}"></i>`).join('')}</div>${infoLine('本次支出',fmt(s.clinic*100),'LNY')}${infoLine('医疗预算',fmt(s.healthFunds),'LNY')}${infoLine('累计接诊',s.visits,'人')}</div></div>`,roomFooter(i,scenicButton('完成接诊并结算','clinic',s.clinic<=0||s.clinic>s.backlog||s.clinic*100>s.healthFunds?'disabled':''),'医疗预算与培训预算分别记账。'));}
}
// Scene-specific objects change actual local simulation state.
function receipt(text){document.querySelector('.result-receipt')?.remove();const el=document.createElement('aside');el.className='result-receipt';el.setAttribute('role','status');el.innerHTML=`<small>ACTION RECEIPT · 第 ${s.day} 日</small><p>${esc(text)}</p><button data-cmd="dismiss-receipt">继续</button>`;document.body.append(el);}
commands['dismiss-receipt']=()=>document.querySelector('.result-receipt')?.remove();
commands['energy-shift']=b=>{s.powerSteel=Math.max(0,Math.min(200,s.powerSteel+(b.dataset.id==='steel'?10:-10)));save();renderRoom();};
commands['batch-days']=b=>{s.batchDays=Number(b.dataset.id);save();renderRoom();};
commands['run-batch']=()=>{const before={ore:s.ore,steel:s.steel,machines:s.machines,cash:s.cash},n=s.batchDays||1;advance(n);receipt(`${n} 日批次完成。矿石消耗 ${fmt(before.ore-s.ore)} tonne，机械增加 ${s.machines-before.machines} equipment_unit，现金支出 ${fmt(before.cash-s.cash)} LNY。钢材期末 ${s.steel} tonne。`);};
commands['class-seat']=b=>{if(s.programme&&!s.programme.done)return;const n=(Number(b.dataset.id)+1)*5;s.seats=Math.min(s.seats===n?n-5:n,80,s.low,Math.floor(s.funds/2000));save();renderRoom();};
commands['patient-group']=b=>{const n=Math.min(60,(Number(b.dataset.id)+1)*10,s.backlog,Math.floor(s.healthFunds/100));s.clinic=s.clinic===n?Math.max(0,n-10):n;save();renderRoom();};
commands.pack=()=>{if(s.quantity<=0||s.quantity>s.supply[s.supplier]||quote().total>s.cash)return;s.manifest={supplier:s.supplier,quantity:s.quantity,tariff:s.tariff,total:quote().total};save();renderRoom();};
commands.unpack=()=>{s.manifest=null;save();renderRoom();};
const originalShip=commands.ship;
commands.ship=()=>{const m=s.manifest;if(!m||m.quantity!==s.quantity||m.supplier!==s.supplier||m.tariff!==s.tariff||m.total!==quote().total){s.manifest=null;save();renderRoom();toast('货源或报价已变化，请重新配货');return;}const count=s.shipments.length;originalShip();if(s.shipments.length>count){s.manifest=null;save();}};
const originalSupplier=commands.supplier;commands.supplier=b=>{s.manifest=null;originalSupplier(b);};
commands['open-book']=()=>{if(s.bond)return;s.auction={offer:s.bondOffer,allocations:[0,0],openedDay:s.day};save();renderRoom();};
commands['allocate-bid']=b=>{if(!s.auction||s.bond)return;const j=Number(b.dataset.id),d=Number(b.dataset.delta)*1e6,current=s.auction.allocations[j],other=s.auction.allocations[1-j];s.auction.allocations[j]=Math.max(0,Math.min([12e6,8e6][j],s.auction.offer-other,current+d));save();renderRoom();};
commands['allocate-fill']=()=>{if(!s.auction||s.bond)return;const offer=s.auction.offer;s.auction.allocations=[Math.min(offer,12e6),Math.min(Math.max(0,offer-12e6),8e6)];save();renderRoom();};
commands.issue=()=>{if(s.bond||!s.auction||s.auction.offer!==s.bondOffer)return;const a=s.auction.allocations.reduce((x,y)=>x+y,0);if(a<=0||a>s.bondOffer)return;s.bond={allocated:a,net:a*.98-200000,day:s.day+1,maturity:s.day+361,allocations:[...s.auction.allocations]};record('债券配售 '+compact(a)+' LNY，等待交割',{face:money(a),net:money(s.bond.net),settlement:day(s.bond.day)});renderRoom();toast('配售完成，次日交割入账');};
function pledgeState(){s.pledges??=[[false,false],[false,false]];}
function pledgeLimit(){pledgeState();return Math.max(0,s.pledges[s.bank].reduce((sum,on,j)=>sum+(on?[[10e6,6e6],[5e6,3e6]][s.bank][j]:0),0)*.8-s.banks[s.bank].loan);}
commands.pledge=b=>{pledgeState();const j=Number(b.dataset.id),selected=s.pledges[s.bank],values=[[10e6,6e6],[5e6,3e6]][s.bank];const after=selected.reduce((sum,on,i)=>sum+((i===j?!on:on)?values[i]:0),0)*.8;if(after<s.banks[s.bank].loan){toast('该抵押品仍担保未偿贷款');return;}selected[j]=!selected[j];s.amount=Math.min(s.amount||s.banks[s.bank].gap,pledgeLimit(),s.cash);save();renderRoom();};
const originalLend=commands.lend;commands.lend=()=>{if(s.amount>pledgeLimit()||s.amount<=0)return;originalLend();};
const originalBank=commands.bank;commands.bank=b=>{originalBank(b);s.amount=Math.min(s.amount,pledgeLimit(),s.cash);save();renderRoom();};
// Keep the player inside the location after an action; a receipt reflects only recorded changes.
for(const name of ['enact','fund-commit','issue','lend','announce-rate','fx','expand','ship','train','match','clinic','commitment']){const fn=commands[name];commands[name]=b=>{const current=view,previous=s.log[0];fn(b);if(typeof current==='number'){view=current;pathTo('scene/'+role+'/'+view,true);renderRoom();}if(s.log[0]!==previous)receipt(s.log[0]?.text||'行动已记录');};}
const firstFinanceScene=financeScene;
financeScene=function(i){if(i!==1)return firstFinanceScene(i);const a=s.bond?.allocated??s.auction?.allocations.reduce((x,y)=>x+y,0)??0;scene('exchange','主权债券发行','发行面值决定融资上限，买盘决定实际成交。低于面值发行，到账现金少于未来偿还本金。',`<div class="exchange-stage"><div class="market-board"><div class="board-header"><span>${s.auction?'申购簿已开市':'申购簿待开启'}</span><b>98.00 <small>% 面值</small></b></div>${['国内银行','其他投资者'].map((n,j)=>`<div class="bid-lane"><span>0${j+1}</span>${glyph(j?'person':'bank')}<div><h3>${n}</h3><div class="order-depth"><i style="width:${j?66.7:100}%"></i></div><div class="allocation-actions"><button data-cmd="allocate-bid" data-id="${j}" data-delta="-1" ${!s.auction||s.bond?'disabled':''} aria-label="减少${n}配售">−</button><strong>${compact(s.bond?.allocations?.[j]??s.auction?.allocations[j]??0)}</strong><button data-cmd="allocate-bid" data-id="${j}" data-delta="1" ${!s.auction||s.bond?'disabled':''} aria-label="增加${n}配售">+</button></div></div><strong>${j?8:12}M<small>LNY 申购</small></strong></div>`).join('')}<div class="market-note">每次配售 1M LNY · 固定样例买盘</div>${s.auction&&!s.bond?'<button class="text-button" data-cmd="allocate-fill">按申购额配满</button>':''}</div><div class="issuance-control">${s.bond?specimen('seal','已发行面值',compact(a),'LNY'):dial('拟发行面值','bondOffer',s.bondOffer,1e6,40e6,1e6,'LNY')}</div><aside class="trade-ticket"><span class="instrument-label">ALLOCATION TICKET</span><h3>${s.bond?(s.settled?'交割完成':'等待交割'):'本次配售'}</h3>${infoLine('配售面值',compact(a),'LNY')}${infoLine('净到账',compact(a?a*.98-200000:0),'LNY')}${infoLine('到期本息',compact(a*1.03),'LNY')}${infoLine('未配售',compact(s.bondOffer-a),'LNY')}<p>发行费用 0.2M LNY<br>年票息 3% · 360 日到期<br>交割前不会增加可用现金。</p></aside></div>`,roomFooter(i,s.bond?scenicButton('推进至下一事件','next-event',Number.isFinite(nextEvent())?'':'disabled'):s.auction?scenicButton('确认配售','issue',a<=0?'disabled':''):scenicButton('开启申购簿','open-book')));};
const firstReserveScene=reserveScene;
reserveScene=function(i){if(i!==0)return firstReserveScene(i);pledgeState();s.amount=Math.min(s.amount,pledgeLimit(),s.cash);firstReserveScene(i);const instrument=document.querySelector('.loan-instrument');const limit=Math.min(s.cash,pledgeLimit());patchChildrenHTML(instrument,`<span class="instrument-label">COLLATERAL / 抵押组合</span><div class="collateral-lots">${['国债','合格信贷资产'].map((name,j)=>`<button class="collateral-lot ${s.pledges[s.bank][j]?'selected':''}" data-cmd="pledge" data-id="${j}">${s.pledges[s.bank][j]?'✓ ':''}${name}<br>${compact([[10e6,6e6],[5e6,3e6]][s.bank][j])} LNY</button>`).join('')}</div>${controlRail('本次贷款','amount',s.amount,0,limit,200000,'LNY')}${infoLine('剩余额度',compact(limit),'LNY')}${infoLine('固定年利率',(s.rate+.5).toFixed(2),'%')}<p class="object-caption">抵押折扣 20% · 7 日到期。未偿还前不能解除对应抵押。</p>`);const btn=document.querySelector('[data-cmd=lend]');btn.disabled=s.amount<=0||s.amount>limit;};
document.addEventListener('input',e=>{const key=e.target.dataset.control;if(key){const out=document.querySelector(`[data-output="${key}"]`);if(out)out.textContent=fmt(s[key]);if(key==='bondOffer'&&s.auction&&!s.bond){s.auction=null;save();}if(['quantity','tariff'].includes(key)&&s.manifest){s.manifest=null;save();}}});
document.addEventListener('dragstart',e=>{const b=e.target.closest('[data-energy]');if(b)e.dataTransfer.setData('energy',b.dataset.energy);});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-energy-drop]'))e.preventDefault();});
document.addEventListener('drop',e=>{const target=e.target.closest('[data-energy-drop]');if(!target)return;e.preventDefault();const from=e.dataTransfer.getData('energy');if(from&&from!==target.dataset.energyDrop)commands['energy-shift']({dataset:{id:target.dataset.energyDrop}});});
function spaceForModule(m){const t=m.title;if(/峰会|外交|谈判|制裁|联合|迁移/.test(t))return'diplomacy';if(/债券|债务|资产购买|外汇|互换/.test(t))return'exchange';if(m.role==='CAPTAIN')return'cabinet';if(m.role==='FINANCE')return'treasury';if(m.role==='CENTRAL_BANK')return'reserve';if(m.role==='TRADE')return'harbor';if(/医疗|健康|接诊|疫情/.test(t))return'clinic';if(/教育|培训|人才|学位|研究/.test(t))return'academy';if(m.role==='SOCIAL')return'commons';if(/电|能源|排放|储备/.test(t))return'power';if(/勘探|建设|项目|扩建|设施/.test(t))return'construction';return'factory';}
openCodex=function(filter=''){view='codex';sceneSection='';catalogFilter=filter;catalogQuery='';pathTo('actions');renderCodex();};
renderCodex=function(){view='codex';const mods=catalog.modules.filter(m=>m.role===roles[role].code),filtered=mods.filter(m=>(catalogFilter===''||roomFor(m)===Number(catalogFilter))&&(!catalogQuery||(m.title+' '+m.fields.map(f=>f.label+' '+f.sourceQuote).join(' ')).toLowerCase().includes(catalogQuery.toLowerCase())));scene(roomSpaces[role][0],'进阶行动','完整政策与协作事项。各地点保留对应的数量、价格、期限与条款。',`<div class="scene-search"><input id="catalog-search" value="${esc(catalogQuery)}" placeholder="搜索行动或指标" aria-label="搜索行动"><button class="text-button" data-cmd="catalog-filter" data-id="">全部 ${mods.length} 项</button><button class="text-button" data-cmd="policies">已保存行动</button></div><div class="location-actions">${filtered.map(m=>`<button class="location-door" style="--door:url('assets/${spaceForModule(m)}.png')" data-cmd="module" data-id="${m.id}" data-module-card="${m.id}"><small>${spaces[spaceForModule(m)].english}</small><strong>${esc(m.title==='VAT'?'增值税':m.title)}</strong><span>${m.fields.length} 项设置 · ${data.policies[m.id]?'已保存 v'+data.policies[m.id].version:'进入场景'} ↗</span></button>`).join('')||'<p>没有匹配的行动</p>'}</div>`,roomFooter(0,'','复杂政策保留参数，不自动产生未经建模的结果。'));};
openModule=function(id){const m=catalog.modules.find(m=>m.id===id&&m.role===roles[role].code);if(!m)return;activeModule=m;editValues=structuredClone(data.policies[id]?.values||Object.fromEntries(m.fields.map(f=>[f.key,f.value??(f.type==='number'?0:'')])));editorTab='全部';view='module';fieldIndex=0;fieldPage='controls';pathTo('action/'+id+'/0');renderEditor();};
function objectField(f){const v=editValues[f.key];if(['select','multi'].includes(f.type))return `<div class="field" data-field-wrap="${f.key}"><div class="object-options">${(f.options||[]).map((o,j)=>`<button class="choice-object ${(f.type==='multi'?(v||[]).includes(o):v===o)?'selected':''}" data-cmd="field-choice" data-id="${f.key}" data-choice="${j}">${glyph(/银行|金融/.test(o)?'bank':/人|劳动/.test(o)?'person':/港|船|运输/.test(o)?'ship':'seal')}${esc(o)}</button>`).join('')}</div><details><summary>规则来源 · ${esc(f.source)}</summary><span data-no-translate>${esc(f.sourceQuote)}</span></details></div>`;if(['table','conditions'].includes(f.type)){const rows=Array.isArray(v)?v:[];return `<div class="field" data-field-wrap="${f.key}"><div data-structured="${f.key}">${rows.map((r,j)=>`<div class="clause-object"><h3>${f.type==='conditions'?'执行条件':'资源条目'} ${j+1}</h3>${structuredRow(f,r,j)}</div>`).join('')||'<p class="object-caption">尚无条目。添加资源对象及对应数量。</p>'}</div>${scenicButton('添加条目','add-row',`data-id="${f.key}"`,true)}<details><summary>规则来源 · ${esc(f.source)}</summary><span data-no-translate>${esc(f.sourceQuote)}</span></details></div>`;}return renderField(f);}
function displayValue(f){const v=editValues[f.key];if(Array.isArray(v))return ['conditions','table'].includes(f.type)?`${v.length} 项条目`:v.join('、')||'未选择';return `${v??'未设置'}${f.type==='number'?' '+fieldUnit(f):''}`;}
renderEditor=function(){if(!activeModule)return;const m=activeModule;fieldIndex=Math.max(0,Math.min(fieldIndex,m.fields.length-1));const f=m.fields[fieldIndex],saved=data.policies[m.id],mode=fieldPage;sceneSection='进阶行动 · '+m.id;const modes=`<div class="operation-mode">${[['controls','操作'],['review','核对'],['results','结果']].map(([k,n])=>`<button data-cmd="operation-mode" data-id="${k}" class="${mode===k?'active':''}">${n}</button>`).join('')}</div>`;let body='';if(mode==='controls'&&f){body=`<div class="operation-stage"><nav class="operation-navigation" aria-label="行动设置">${m.fields.map((x,j)=>`<button class="operation-step ${j===fieldIndex?'active':''}" data-cmd="field-jump" data-id="${j}" data-field-link="${x.key}"><b>${String(j+1).padStart(2,'0')}</b>${esc(x.label)}</button>`).join('')}</nav><div class="operation-object">${glyph(f.type==='number'?'coin':f.type==='select'?'seal':'book')}<h2>${esc(f.label)}</h2>${objectField(f)}<div class="step-pager"><button data-cmd="field-jump" data-id="${fieldIndex-1}" ${fieldIndex===0?'disabled':''}>← 上一项</button><span>${fieldIndex+1} / ${m.fields.length}</span>${fieldIndex===m.fields.length-1?'<button data-cmd="operation-mode" data-id="review">核对行动 →</button>':`<button data-cmd="field-jump" data-id="${fieldIndex+1}">下一项 →</button>`}</div></div><aside class="operation-notes"><h3>${esc(f.tab||'行动参数')}</h3><p>${f.type==='number'?'调整数量后，单位与数值一同记录。':f.type==='multi'?'可同时选择多个对象。':f.type==='select'?'选择参与本次行动的对象或规则。':'条目保留具体对象、数量和单位。'}</p><p>${f.plan?'该项为跨职位协作请求。':'完整参数按同一版本保存。'}</p><p>当前记录<br><strong>${saved?'v'+saved.version+' · '+saved.status:'尚未保存'}</strong></p><button class="text-button" data-cmd="source-module">查看规格原文</button></aside></div>`;}else if(mode==='review'){body=`<div class="review-items">${m.fields.map((x,j)=>`<button class="review-item" data-cmd="field-jump" data-id="${j}"><span>${esc(x.label)}</span><strong>${esc(displayValue(x))}</strong></button>`).join('')}</div>`;}else{body=`<div class="review-items">${m.readouts.map(o=>`<div class="review-item" data-readout="${o.source}"><span>${esc(o.label)}</span><strong>待结算</strong></div>`).join('')||'<p>该行动没有独立结果字段。</p>'}</div><p class="object-caption">结果尚未连接正式结算引擎。</p>`;}scene(spaceForModule(m),esc(m.title==='VAT'?'增值税':m.title),'每次处理一个对象。核对后保存完整版本，联合事项另需会签。',modes+body,`<div class="footer-left">${mode==='review'?scenicButton('保存行动版本','save-policy'):scenicButton('核对完整行动','operation-mode','data-id="review"')}<span class="footer-note">${saved?'v'+saved.version+' · '+saved.status:'本地参数配置 · 尚未进入正式结算'}</span></div><div class="footer-right"><button class="text-button" data-cmd="codex">返回进阶行动</button></div>`,'operation');};
commands['field-jump']=b=>{fieldIndex=Number(b.dataset.id);fieldPage='controls';pathTo('action/'+activeModule.id+'/'+fieldIndex);renderEditor();};
commands['operation-mode']=b=>{fieldPage=b.dataset.id;pathTo('action/'+activeModule.id+'/'+fieldPage);renderEditor();};
commands['field-choice']=b=>{const f=activeModule.fields.find(f=>f.key===b.dataset.id),v=f.options[Number(b.dataset.choice)];if(f.type==='multi'){const before=editValues[f.key]||[];editValues[f.key]=before.includes(v)?before.filter(x=>x!==v):[...before,v];}else editValues[f.key]=v;renderEditor();};
commands['back-editor']=()=>renderEditor();
commands['save-policy']=()=>{const before=data.policies[activeModule.id]?.version;oldSavePolicy();if(data.policies[activeModule.id]?.version!==before)receipt('行动版本已保存。规则校验与会签完成后才能进入正式结算。');};
const bootHash=location.hash;let didBoot=false;
const immersiveSetRole=setRole;
setRole=function(r){document.querySelector('.result-receipt')?.remove();sceneSection='';immersiveSetRole(r);if(!didBoot){didBoot=true;if(bootHash)setTimeout(()=>routeFromHash(bootHash),0);}};
function routeFromHash(hash=location.hash){if(!catalog)return;const bits=hash.slice(1).split('/');routeQuiet=true;try{if(bits[0]==='scene'&&roles[bits[1]]){if(role!==bits[1])setRole(bits[1]);showRoom(Math.max(0,Math.min(2,Number(bits[2])||0)));}else if(bits[0]==='action'){const m=catalog.modules.find(m=>m.id===bits[1]);if(m){const r=Object.keys(roles).find(r=>roles[r].code===m.role);if(r!==role)setRole(r);openModule(m.id);if(['review','results'].includes(bits[2]))fieldPage=bits[2];else fieldIndex=Number(bits[2])||0;renderEditor();}}else if(bits[0]==='actions')openCodex();else commands.close();}finally{routeQuiet=false;history.replaceState(null,'',`?role=${role}${countryScope?'&country='+countryScope:''}${hash||'#map'}`);}}
window.addEventListener('popstate',()=>routeFromHash());
