roles.finance.cards[1][1]='债券发行';roles.finance.cards[1][2]='申购、配售、交割依次完成';
const basicRoomFooter=roomFooter;
roomFooter=function(i,action='',note=''){const next=nextEvent();return basicRoomFooter(i,action,note)+`<nav class="scene-wayfinding" aria-label="地点导航">${roles[role].cards.map((x,j)=>`<button class="${i===j?'active':''}" data-cmd="room" data-id="${j}"><small>0${j+1}</small>${x[1]}</button>`).join('')}${Number.isFinite(next)&&next>s.day?`<button class="event-link" data-cmd="next-event">第 ${next} 日 · 下一事件 →</button>`:''}</nav>`;};
const closeImmersive=commands.close;commands.close=()=>{document.querySelector('.result-receipt')?.remove();closeImmersive();};
const basicOpenRoom=showRoom;showRoom=function(i){document.querySelector('.result-receipt')?.remove();basicOpenRoom(i);};
const simpleReceipt=receipt;
receipt=function(text){simpleReceipt(text);const nextRoom=role==='finance'?(view===0?1:2):role==='captain'?2:role==='trade'?2:role==='social'?(view===0?1:view):role==='industry'?1:view;if(typeof nextRoom==='number'&&nextRoom!==view){const b=document.createElement('button');b.dataset.cmd='room';b.dataset.id=nextRoom;b.textContent='前往'+roles[role].cards[nextRoom][1]+' →';document.querySelector('.result-receipt')?.append(b);}};
clampControl=function(key,v){const el=document.querySelector(`.immersive-scene [data-control="${key}"]`)||document.querySelector(`[data-control="${key}"]`);if(!el)return 0;const min=Number(el.min),max=Number(el.max);if(['seats','match','clinic'].includes(key))v=Math.floor(v);return Math.min(max,Math.max(min,Number.isFinite(v)?v:min));};
commands.nudge=b=>{const input=document.querySelector(`.immersive-scene input[type=range][data-control="${b.dataset.id}"]`);if(!input)return;input.value=String(Math.min(Number(input.max),Math.max(Number(input.min),Number(input.value)+Number(input.step||1)*Number(b.dataset.delta))));input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));};
